<?php
require __DIR__ . '/includes/auth.php';
$adminTitle='Testimonials';$errors=[];$edit=null;
if(isset($_GET['edit'])){$stmt=db()->prepare('SELECT * FROM testimonials WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch();}
if(is_post()){
 verify_csrf();$action=$_POST['action']??'save';
 if($action==='delete'){db()->prepare('DELETE FROM testimonials WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Testimonial deleted.');redirect('admin/testimonials.php');}
 $id=(int)($_POST['id']??0);$name=trim($_POST['client_name']??'');$location=trim($_POST['location']??'');$quote=trim($_POST['quote']??'');$rating=max(1,min(5,(int)($_POST['rating']??5)));$sort=(int)($_POST['sort_order']??0);$active=isset($_POST['is_active'])?1:0;
 if($name==='')$errors[]='Client name is required.';if($quote==='')$errors[]='Testimonial text is required.';
 if(!$errors){if($id){$stmt=db()->prepare('UPDATE testimonials SET client_name=?,location=?,quote=?,rating=?,sort_order=?,is_active=? WHERE id=?');$stmt->execute([$name,$location,$quote,$rating,$sort,$active,$id]);}else{$stmt=db()->prepare('INSERT INTO testimonials(client_name,location,quote,rating,sort_order,is_active) VALUES(?,?,?,?,?,?)');$stmt->execute([$name,$location,$quote,$rating,$sort,$active]);}flash('success','Testimonial saved.');redirect('admin/testimonials.php');}
 $edit=['id'=>$id,'client_name'=>$name,'location'=>$location,'quote'=>$quote,'rating'=>$rating,'sort_order'=>$sort,'is_active'=>$active];
}
$items=db()->query('SELECT * FROM testimonials ORDER BY sort_order,id')->fetchAll();
require __DIR__ . '/includes/header.php';
?>
<div class="grid gap-7 xl:grid-cols-[420px_1fr]"><section class="admin-card p-6"><h2 class="font-display text-2xl font-bold uppercase text-brand-950"><?= $edit?'Edit Testimonial':'Add Testimonial' ?></h2><?php if($errors): ?><div class="mt-4 rounded-xl bg-red-50 p-4 text-sm font-bold text-red-700"><?= e(implode(' ',$errors)) ?></div><?php endif; ?><form method="post" class="mt-6 grid gap-4"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="grid gap-2 text-sm font-bold">Client Name<input class="form-input" name="client_name" value="<?= e($edit['client_name']??'') ?>" required></label><label class="grid gap-2 text-sm font-bold">Location<input class="form-input" name="location" value="<?= e($edit['location']??'') ?>"></label><label class="grid gap-2 text-sm font-bold">Testimonial<textarea class="form-input min-h-40" name="quote" required><?= e($edit['quote']??'') ?></textarea></label><div class="grid grid-cols-2 gap-4"><label class="grid gap-2 text-sm font-bold">Rating<select class="form-input" name="rating"><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>" <?= (int)($edit['rating']??5)===$i?'selected':'' ?>><?= $i ?> stars</option><?php endfor; ?></select></label><label class="grid gap-2 text-sm font-bold">Sort Order<input type="number" class="form-input" name="sort_order" value="<?= e($edit['sort_order']??0) ?>"></label></div><label class="flex items-center gap-3 text-sm font-bold"><input type="checkbox" name="is_active" class="h-5 w-5" <?= ($edit['is_active']??1)?'checked':'' ?>>Visible on website</label><div class="flex gap-3"><button class="rounded-xl bg-brand-700 px-5 py-3 font-extrabold text-white">Save Testimonial</button><?php if($edit): ?><a href="<?= url('admin/testimonials.php') ?>" class="rounded-xl bg-slate-100 px-5 py-3 font-extrabold">Cancel</a><?php endif; ?></div></form></section><section class="admin-card p-6"><h2 class="font-display text-2xl font-bold uppercase text-brand-950">All Testimonials</h2><div class="mt-5 grid gap-4"><?php foreach($items as $item): ?><article class="rounded-2xl border border-slate-200 p-5"><div class="flex items-start justify-between gap-4"><div><div class="font-extrabold text-brand-950"><?= e($item['client_name']) ?></div><div class="text-xs text-slate-500"><?= e($item['location']) ?></div></div><span class="status-badge <?= $item['is_active']?'bg-emerald-100 text-emerald-700':'bg-slate-100 text-slate-600' ?>"><?= $item['is_active']?'Active':'Hidden' ?></span></div><p class="mt-4 text-sm leading-6 text-slate-600">“<?= e($item['quote']) ?>”</p><div class="mt-4 flex gap-2"><a href="?edit=<?= (int)$item['id'] ?>" class="rounded-lg bg-blue-50 p-2 text-blue-700"><i data-lucide="pencil" class="h-4 w-4"></i></a><form method="post" data-confirm="Delete this testimonial?"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="rounded-lg bg-red-50 p-2 text-red-700"><i data-lucide="trash-2" class="h-4 w-4"></i></button></form></div></article><?php endforeach; ?></div></section></div>
